/**
 * Столкновения.
 *
 * Отдельных данных о проходимости в оригинале нет. Опора определяется двумя
 * условиями сразу:
 *
 *     твёрдо = в проверяемых 4 пикселях ЕСТЬ пиксели И бит 6 атрибута СБРОШЕН
 *
 * Яркость работает наоборот интуиции: она помечает декорацию, сквозь которую
 * проходят насквозь. В стартовой комнате яркие стол, факелы и висящий призрак —
 * встать на них нельзя, и это сходится с поведением игры.
 *
 * Перенос $F947 (опора под ногами) и $F97F с $F91D (упор при ходьбе вбок).
 */
import { CELL_COLUMNS, SCREEN_HEIGHT, SCREEN_WIDTH, type RenderedRoom } from "./room.js";

/** Бит 6 атрибута. Установлен — значит проходимо насквозь. */
export const BRIGHT_BIT = 0x40;

/** Ширина одной проверяемой группы в пикселях: половина знакоместа. */
const GROUP_PIXELS = 4;

/**
 * Есть ли пиксели в группе из 4 пикселей, начинающейся с единицы X,
 * и при этом не яркое ли знакоместо.
 *
 * xUnit — координата в единицах по 4 пикселя, y — в пикселях.
 */
export function isSolidAt(room: RenderedRoom, xUnit: number, y: number): boolean {
  if (y < 0 || y >= SCREEN_HEIGHT) return false;
  const x0 = xUnit * GROUP_PIXELS;
  if (x0 < 0 || x0 + GROUP_PIXELS > SCREEN_WIDTH) return false;

  const rowBase = y * SCREEN_WIDTH;
  let hasPixels = false;
  for (let i = 0; i < GROUP_PIXELS; i++) {
    if (room.pixels[rowBase + x0 + i]) { hasPixels = true; break; }
  }
  if (!hasPixels) return false;

  // Атрибуты берутся из слоя ПРОХОДИМОСТИ: он совпадает с экранным
  // всюду, кроме знакомест, которым твёрдость назначена мимо экрана
  const attr = room.collisionAttrs[(y >> 3) * CELL_COLUMNS + (x0 >> 3)] ?? 0;
  return (attr & BRIGHT_BIT) === 0;
}

/**
 * Опора под ногами: оригинал щупает ЧЕТЫРЕ группы подряд, начиная с x + 1.
 *
 * Диззи занимает единицы x..x+5, то есть проверяется середина, а не края.
 * Иначе он цеплялся бы за стены плечами.
 */
export function isGroundAt(room: RenderedRoom, x: number, y: number): boolean {
  for (let i = 1; i <= 4; i++) {
    if (isSolidAt(room, x + i, y)) return true;
  }
  return false;
}

/**
 * На сколько пикселей выше ног начинаются пробы упора вбок.
 *
 * Ровно десять: `MOVE_RIGHT_CHECK` ($F8E2) и его левый близнец делают
 * `CALL $F935` (там `probeY = Y`), затем `ADD IX,-20` и `SUB 10`. Двадцать
 * байт таблицы строк — это десять строк, они же десять пикселей.
 */
export const SIDE_PROBE_OFFSET = 10;
/** Шаг между пробами вбок. */
export const SIDE_PROBE_STEP = 4;

/**
 * Упор при движении вбок: три пробы по высоте от ведущего края.
 *
 * Пробы начинаются НЕ от ног, а на 10 пикселей выше опорной точки
 * (в оригинале `probeY -= $0A`), и идут вверх с шагом 4. Ноги остаются
 * неохваченными намеренно: благодаря этому низкий уступ не считается
 * преградой, и Диззи на него взбирается — вместе с подъёмом на 4 пикселя
 * перед проверкой опоры это и даёт ходьбу по уступам.
 */
export function isBlockedSideways(
  room: RenderedRoom,
  probeXUnit: number,
  y: number,
): boolean {
  const top = y - SIDE_PROBE_OFFSET;
  for (let i = 0; i < 3; i++) {
    if (isSolidAt(room, probeXUnit, top - i * SIDE_PROBE_STEP)) return true;
  }
  return false;
}

/**
 * Поиск места, где Диззи помещается целиком и стоит на опоре.
 *
 * Нужно только демонстрационному режиму свободного перехода по комнатам:
 * в самой игре точка входа задаётся тем, откуда Диззи пришёл, и в геометрию
 * он попасть не может. Фиксированная же точка сажает его, например, под стол
 * в комнате 68, где просвет 16 пикселей при росте 20, — и выйти уже нельзя.
 *
 * Проверяем ровно то же, что проверяет движок: под ногами опора, а по всей
 * высоте нет ни одной боковой преграды. Так найденное место заведомо
 * проходимо тем же кодом, что и всё остальное движение.
 */
export function findSpawn(
  room: RenderedRoom, height = 20, preferX = 23, preferY = 175,
): { x: number; y: number } {
  const fits = (x: number, y: number): boolean => {
    if (!isGroundAt(room, x, y + 1)) return false;
    for (let offset = 1; offset <= height; offset += 4) {
      if (isSolidAt(room, x, y - offset)) return false;
      if (isSolidAt(room, x + 5, y - offset)) return false;
    }
    return true;
  };
  if (fits(preferX, preferY)) return { x: preferX, y: preferY };

  // Идём от предпочтительной точки наружу: так выбор остаётся предсказуемым
  for (let radius = 1; radius < 64; radius++) {
    for (const x of [preferX - radius, preferX + radius]) {
      if (x < 2 || x > 56) continue;
      for (let y = preferY; y >= height + 8; y -= 8) {
        if (fits(x, y)) return { x, y };
      }
    }
  }
  return { x: preferX, y: preferY };
}

chegleyev-dizzy3remake-packages-engine-t.text:
/**
 * Сверка физики с эталонными трассами, снятыми с настоящей игры.
 *
 * Трассы сделаны tools/trace.py: одна строка на логический такт, состояние
 * движка целиком. Тест воспроизводит записанный ввод такт за тактом и
 * сравнивает результат. Расхождение на такте N сразу указывает, где порт
 * разошёлся с оригиналом.
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

import { loadGameData } from "../src/data.js";
import { Engine, INPUT_JUMP, INPUT_LEFT, INPUT_RIGHT } from "../src/engine.js";

import objects from "../../../assets/engine/objects.json" with { type: "json" };
import rooms from "../../../assets/engine/rooms.json" with { type: "json" };
import sprites from "../../../assets/engine/sprites.json" with { type: "json" };
import world from "../../../assets/engine/world.json" with { type: "json" };

const data = loadGameData({
  sprites: sprites as never,
  rooms: rooms as never,
  objects: objects as never,
  world: world as never,
});

interface TraceRow {
  frame: number;
  x: number; y: number; vy: number;
  on_ground: number; state: number; input: number;
  step_left: number; step_right: number;
  room: number; probe_x: number; probe_y: number;
  lives: number; busy: number; anim: number; anim_phase: number;
}

/**
 * Ввод для одного такта.
 *
 * Горизонталь берётся НЕ из маски $F5FE, а из пары $F62B/$F62C — это то,
 * по чему движок реально двигался ($F7C3 считает новый X как
 * `x - ($F62B) + ($F62C)`). Маска к моменту выборки бывает уже съедена:
 * на такте смены комнаты и на старте прыжка она читается нулём, хотя шаг
 * при этом сделан. Прыжок же в этой паре не отражается, поэтому его бит
 * по-прежнему берём из маски.
 *
 * Надёжного одного источника тут нет: маска бывает уже съедена, а пара шагов
 * — уже сброшена. Поэтому берётся объединение: шаг засчитан, если о нём
 * говорит хотя бы одно из двух мест.
 */
function inputOf(row: TraceRow): number {
  let mask = row.input & INPUT_JUMP;
  if (row.step_right || row.input & INPUT_RIGHT) mask |= INPUT_RIGHT;
  if (row.step_left || row.input & INPUT_LEFT) mask |= INPUT_LEFT;
  return mask;
}

function loadTrace(name: string): TraceRow[] {
  const path = fileURLToPath(new URL(`../../../tests/golden/${name}.jsonl`, import.meta.url));
  return readFileSync(path, "utf8")
    .split("\n")
    .filter((line) => line.length > 0)
    .map((line) => JSON.parse(line) as TraceRow);
}

/** В трассе скорость лежит байтом; приводим к знаковой. */
function signed(value: number): number {
  return value > 127 ? value - 256 : value;
}

/** Флаги для стартовой комнаты: огонь ещё горит, значит накладка рисуется. */
const START_FLAGS = new Map([["F614", 0]]);

describe.each(["walk_right", "walk_left", "jump", "jump_right", "step_up_47",
  "cross_right", "die_left", "jump_up_left"])(
  "трасса %s",
  (name) => {
    const rows = loadTrace(name);

    it("воспроизводится такт за тактом", () => {
      const first = rows[0]!;
      // Трассы снимаются с уже идущей игры, поэтому фаза анимации и состояние
      // на первом такте не нулевые — иначе кадры разойдутся на ровном месте
      const engine = new Engine(data, {
        room: first.room,
        x: first.x,
        y: first.y,
        flags: START_FLAGS,
        animPhase: first.anim_phase,
        state: first.state,
        // Делитель медленного такта в снапшоте застаёт фазу 2
        slowPhase: 2,
      });

      const mismatches: string[] = [];
      for (let i = 1; i < rows.length; i++) {
        const expected = rows[i]!;
        engine.tick(inputOf(expected));
        const d = engine.dizzy;
        if (d.x !== expected.x || d.y !== expected.y
            || d.vy !== signed(expected.vy) || d.room !== expected.room
            || d.lives !== expected.lives || d.animFrame !== expected.anim) {
          mismatches.push(
            `такт ${expected.frame}: ждали x=${expected.x} y=${expected.y} ` +
            `vy=${signed(expected.vy)} комната=${expected.room} ` +
            `жизни=${expected.lives} кадр=${expected.anim}, ` +
            `получили x=${d.x} y=${d.y} vy=${d.vy} ` +
            `комната=${d.room} жизни=${d.lives} кадр=${d.animFrame}`,
          );
          if (mismatches.length >= 3) break;
        }
      }
      expect(mismatches).toEqual([]);
    });
  },
);

/**
 * Заметка о том, как снимать трассы.
 *
 * Трасса `step_up_47` начинается в комнате 47 — своим ходом туда из стартовой
 * комнаты не дойти, комната задаётся до записи. Задавать её надо ТЕМ ЖЕ путём,
 * что и игра ($F6DB): номер в $F5F2 плюс флаг перерисовки $F5F5. Иначе в
 * буфере столкновений $5B60 остаётся ПРЕДЫДУЩАЯ комната, и трасса выходит про
 * чужую геометрию — на этом я один раз уже обжёгся и полдня искал расхождение
 * физики, которого не было.
 */

chegleyev-dizzy3remake-packages-engine-s.text:
/**
 * Рюкзак: пересечение с предметом, взятие и выкладывание.
 *
 * Перенос $A4AB (прямоугольник), $A782 (обработчик типа 2), $A7B5 (вставка в
 * список) и $F460 (выкладывание). Список несомых предметов лежит в $A77D:
 * ноль — свободный слот, единица — конец списка и одновременно пункт меню
 * «выйти». Вместимость определяется положением этой единицы: сначала два
 * предмета, а после «БЕЗДОННОГО КОЛОДЦА» ($A807) — четыре.
 */
import type { WorldObject } from "./data.js";

/** Смещение системы координат предметов относительно X Диззи ($A4B8). */
const X_BIAS = 0x20;
/** Ширина Диззи в единицах X и высота его прямоугольника в пикселях. */
const DIZZY_WIDTH = 6;
const DIZZY_HEIGHT = 0x12;

/** Идентификатор предмета, расширяющего рюкзак ($A797 -> $A807). */
export const ITEM_EXPANDS_BAG = 0x01;

export interface ItemBox {
  /** X в системе координат предметов. */
  readonly x: number;
  readonly y: number;
  /** Ширина в единицах X и высота в пикселях — из таблицы спрайтов. */
  readonly w: number;
  readonly h: number;
}

/**
 * Пересекается ли Диззи с предметом — дословный перенос $A4AB.
 *
 * Арифметика восьмибитная с переносами, и это важно: сравнение идёт через
 * `SUB`/`ADD` с проверкой флага переноса, а не через «меньше-больше».
 * Прямоугольник Диззи — шесть единиц по X от `x + $20` и $12 пикселей вверх
 * от его Y.
 */
export function overlapsDizzy(
  dizzyX: number, dizzyY: number, item: ItemBox,
): boolean {
  const c = (dizzyX + X_BIAS) & 0xff;
  const b = (dizzyY - DIZZY_HEIGHT) & 0xff;

  // По X: либо предмет правее и не дальше шести единиц, либо левее, но своей
  // шириной достаёт до Диззи
  let a = (item.x - c) & 0xff;
  if (item.x >= c) {
    if (a >= DIZZY_WIDTH) return false;
  } else if (((a - 1 + item.w) & 0x100) === 0) {
    return false;
  }

  a = (item.y - b) & 0xff;
  if (item.y >= b) return a < DIZZY_HEIGHT;
  return ((a - 1 + item.h) & 0x100) !== 0;
}

/**
 * Куда ляжет выложенный предмет — $F460.
 *
 * X выравнивается по чётной единице и сдвигается на `$22`, Y прижимается к
 * границе знакоместа и поднимается на восемь пикселей, но не ниже `$A0`.
 */
export function dropPosition(dizzyX: number, dizzyY: number): {
  x: number; y: number;
} {
  const x = ((dizzyX & 0xfe) + 0x22) & 0xff;
  let y = ((dizzyY & 0xf8) - 8) & 0xff;
  if (y >= 0xa1) y = 0xa0;
  return { x, y };
}

/**
 * Как предметы располагаются в списке.
 *
 * `classic` — как в оригинале: взятое всегда встаёт в ГОЛОВУ, сдвигая
 * остальное, а выложенное сдвигает хвост влево. Из-за этого предмет
 * постоянно меняет своё место в списке.
 *
 * `stable` — поведение ремастера: предмет остаётся в том слоте, где лежал, а
 * новый кладётся в первый свободный. Прокрутка в оригинале нужна была только
 * потому, что выбирать вещь приходилось бегущей подсветкой; при клавишах
 * `1`..`4` и мыши она лишь мешает — номер слота обязан быть постоянным.
 */
export type BagLayout = "classic" | "stable";

/**
 * Список несомых предметов.
 *
 * Хранится ровно как в игре: массив с нулями в свободных слотах и единицей
 * на месте конца. Так вместимость и её расширение получаются сами собой, без
 * отдельного счётчика.
 */
export class Bag {
  private slots: number[];
  readonly layout: BagLayout;

  constructor(slots: readonly number[], layout: BagLayout = "stable") {
    this.slots = [...slots];
    this.layout = layout;
  }

  /** Копия внутреннего представления — для сверки с игрой и сохранений. */
  raw(): number[] {
    return [...this.slots];
  }

  /** Восстановить список целиком — при загрузке сохранения. */
  setRaw(slots: readonly number[]): void {
    this.slots = [...slots];
  }

  /** Индексы несомых предметов, в порядке слотов, без пустых. */
  items(): number[] {
    return this.view().filter((slot): slot is number => slot !== undefined);
  }

  /**
   * Слоты как есть: длина равна вместимости, пустые дают undefined.
   *
   * Именно этим пользуется рюкзак ремастера — номер слота должен совпадать
   * с клавишей, а дырки посередине сохраняться.
   */
  view(): (number | undefined)[] {
    const out: (number | undefined)[] = [];
    for (const slot of this.slots) {
      if (slot === 1) break;
      out.push(slot === 0 ? undefined : slot);
    }
    return out;
  }

  /** Сколько предметов влезает: позиция единицы-конца. */
  capacity(): number {
    const end = this.slots.indexOf(1);
    return end < 0 ? this.slots.length : end;
  }

  full(): boolean {
    return this.items().length >= this.capacity();
  }

  /**
   * Положить предмет в рюкзак.
   *
   * В `classic` — вставка в ГОЛОВУ со сдвигом ($A7C7): ищем первый свободный
   * слот и сдвигаем всё до него на позицию вниз. В `stable` предмет просто
   * ложится в первый свободный слот, ничего не двигая.
   *
   * Возвращает false, если места нет: вызывающий обязан это учесть, иначе
   * предмет исчезнет из мира, не попав в рюкзак.
   */
  insert(index: number): boolean {
    let free = 0;
    while (free < this.slots.length
           && this.slots[free] !== 0 && this.slots[free] !== 1) free++;
    if (free >= this.slots.length || this.slots[free] === 1) return false;
    if (this.layout === "classic") {
      for (let i = free; i > 0; i--) this.slots[i] = this.slots[i - 1]!;
      this.slots[0] = index;
    } else {
      this.slots[free] = index;
    }
    return true;
  }

  /**
   * Убрать предмет из списка.
   *
   * В `classic` — как $F3FC: сдвиг влево ТОЛЬКО до единицы-конца, а
   * освободившийся слот обнуляется. Сама единица остаётся на месте, иначе
   * вместимость схлопывалась бы с каждым выложенным предметом.
   *
   * В `stable` слот просто пустеет, остальные не двигаются.
   */
  remove(index: number): boolean {
    let at = this.slots.indexOf(index);
    if (at < 0) return false;
    if (this.layout === "classic") {
      while (at + 1 < this.slots.length && this.slots[at + 1] !== 1) {
        this.slots[at] = this.slots[at + 1]!;
        at++;
      }
    }
    this.slots[at] = 0;
    return true;
  }

  /** Последний занятый слот — его содержимое выкладывается при полном рюкзаке. */
  last(): number | undefined {
    const items = this.items();
    return items[items.length - 1];
  }

  /** Расширение рюкзака до четырёх мест — $A807. */
  expand(endMarkerAt: number): void {
    const at = this.slots.indexOf(1);
    if (at >= 0) this.slots[at] = 0;
    while (this.slots.length <= endMarkerAt) this.slots.push(0);
    this.slots[endMarkerAt] = 1;
  }
}

/** Прямоугольник предмета по его записи и таблице спрайтов. */
export function itemBox(
  item: WorldObject, sprite: { w: number; h: number },
): ItemBox {
  return { x: item.x, y: item.y, w: sprite.w, h: sprite.h };
}

dev-vpa-dizzy-adventures-remake-core-pla.text:
extends CharacterBody2D

## Dizzy player: platform movement, somersault jump, item pickup/drop.

const GRAVITY := 1960.0
const MOVE_SPEED := 280.0
const JUMP_VELOCITY := -640.0
const FALL_DEATH_Y := 784.0

const PICKUP_SCENE := preload("res://core/items/pickup_item.tscn")

@onready var sprite: DizzySprite = $DizzySprite
@onready var pickup_area: Area2D = $PickupArea
@onready var _screen_container: Node2D = get_parent().get_node("ScreenContainer")

var _facing: int = 1
var _spawn_position: Vector2
var _action_queued := false
var _hazard_cooldown := 0.0
var _blocked_edges: Dictionary = {}


func _ready() -> void:
	add_to_group("player")
	_spawn_position = global_position


func request_action() -> void:
	_action_queued = true


func _physics_process(delta: float) -> void:
	if not is_inside_tree():
		return

	if not is_on_floor():
		velocity.y += GRAVITY * delta

	var direction := Input.get_axis("move_left", "move_right")
	velocity.x = direction * MOVE_SPEED

	if direction != 0:
		_facing = 1 if direction > 0 else -1
		sprite.set_facing(_facing)

	if Input.is_action_just_pressed("jump") and is_on_floor():
		velocity.y = JUMP_VELOCITY
		AudioManager.play_sfx("jump", -4.0)

	move_and_slide()
	ScreenManager.clamp_player_to_bounds(self, _screen_container)
	if _hazard_cooldown > 0.0:
		_hazard_cooldown -= delta
	_tick_edge_blocks(delta)
	_handle_inventory_input()
	_try_action_nearby()
	_check_fall_death()
	_check_screen_edge()


func _handle_inventory_input() -> void:
	if Input.is_action_just_pressed("inventory_next"):
		Inventory.select_next()
	if Input.is_action_just_pressed("drop"):
		_try_drop_item()
	if Input.is_action_just_pressed("use_item"):
		Inventory.try_use_selected()


func _try_action_nearby() -> void:
	var wants_action := _action_queued or Input.is_action_just_pressed("action")
	if not wants_action:
		return
	_action_queued = false

	var nearby_pickups: Array[Area2D] = []
	for area in pickup_area.get_overlapping_areas():
		if area.is_in_group("pickup") and area.has_method("try_pick_up"):
			nearby_pickups.append(area)
	nearby_pickups.sort_custom(_pickup_is_closer)
	for area in nearby_pickups:
		if area.call("try_pick_up"):
			return

	for node in get_tree().get_nodes_in_group("interactable"):
		if node is Area2D and (node as Area2D).overlaps_body(self):
			if node.has_method("try_interact") and node.call("try_interact"):
				return

	for area in pickup_area.get_overlapping_areas():
		if area.is_in_group("interactable") and area.has_method("try_interact"):
			if area.call("try_interact"):
				return


func _pickup_is_closer(first: Area2D, second: Area2D) -> bool:
	var first_distance := first.global_position.distance_squared_to(global_position)
	var second_distance := second.global_position.distance_squared_to(global_position)
	if is_equal_approx(first_distance, second_distance):
		return first.get_instance_id() < second.get_instance_id()
	return first_distance < second_distance


func drop_item() -> void:
	_try_drop_item()


func use_item() -> void:
	Inventory.try_use_selected()


func _try_drop_item() -> void:
	var item_id := Inventory.try_drop_selected()
	if item_id.is_empty():
		return

	if _screen_container.get_child_count() == 0:
		return

	var screen := _screen_container.get_child(0) as Node2D
	var drop_pos := global_position + Vector2(float(_facing) * 24.0, -16.0)
	var uid := SaveGame.record_drop(ScreenManager.current_screen_id, item_id, drop_pos)
	var pickup: Area2D = PICKUP_SCENE.instantiate()
	pickup.item_id = item_id
	pickup.display_name = ItemCatalog.get_display_name(item_id)
	if not uid.is_empty():
		pickup.world_id = "drop/%s" % uid
		pickup.set_meta("ground_uid", uid)
	screen.add_child(pickup)
	pickup.global_position = drop_pos
	AudioManager.play_sfx("drop")


func _check_fall_death() -> void:
	if _hazard_cooldown > 0.0:
		return
	if global_position.y >= FALL_DEATH_Y:
		_handle_death()


func die_from_hazard() -> void:
	if _hazard_cooldown > 0.0:
		return
	_hazard_cooldown = 0.6
	_handle_death()


func _handle_death() -> void:
	if not is_inside_tree():
		return
	AudioManager.play_sfx("death")
	var game_over := Lives.lose_life()
	if game_over:
		GameManager.quit_to_main_menu()
		return

	global_position = _spawn_position
	velocity = Vector2.ZERO


func _check_screen_edge() -> void:
	if not is_inside_tree():
		return
	var tree := get_tree()
	if tree == null:
		return
	var world := tree.get_first_node_in_group("game_world")
	if world and world.has_method("request_edge_transition"):
		world.call("request_edge_transition", self)


func on_screen_entered(_screen_id: String) -> void:
	velocity = Vector2.ZERO
	_spawn_position = global_position
	_hazard_cooldown = 1.0
	_blocked_edges.erase("up")
	_blocked_edges.erase("down")


func is_edge_blocked(edge: String) -> bool:
	return _blocked_edges.get(edge, 0.0) > 0.0


func block_edge(edge: String, duration: float) -> void:
	if duration <= 0.0:
		return
	_blocked_edges[edge] = maxf(_blocked_edges.get(edge, 0.0), duration)


func _tick_edge_blocks(delta: float) -> void:
	if _blocked_edges.is_empty():
		return
	var expired: Array[String] = []
	for edge in _blocked_edges:
		_blocked_edges[edge] -= delta
		if _blocked_edges[edge] <= 0.0:
			expired.append(edge)
	for edge in expired:
		_blocked_edges.erase(edge)

