PREDICATE_M(core, colliderSnapDistance, 5)
{
	int x1 = A1;
	int y1 = A2;
	int x2 = A3;
	int y2 = A4;

	int dist = 0; // max distance from box bottom to collider top (if collider top is inside box)
	for(auto obj: g_game.m_collider)
	{
