		if(!(obj->collider & COLLIDER_HARD)) continue; // only those that need it
		iRect c = obj->rect();
		if( x2<=c.p1.x || x1 >= c.p2.x ) continue; // not intersecting
		if(y1 <= c.p1.y && c.p1.y < y2) dist = std::max(dist,y2-c.p1.y);
	}
	return A5 = dist;
}

